def evaluate_classifier(outputs, expected):
    if not outputs or not expected:
        return 0.0
    total = min(len(outputs), len(expected))
    correct = sum(
        1
        for o, e in zip(outputs, expected)
        if str(o).strip().lower() == str(e).strip().lower()
    )
    return float(correct / total)


if __name__ == "__main__":
    print(evaluate_classifier(["Positive", "negative"], ["positive", "Negative"]))
